def interpolate(g, bg, marker, maxgap=6):
 R,C=len(g),len(g[0]); mark=set()
 # scanning each row, background runs bounded by marker cells
 for r in range(R):
  c=0
  while c<C:
   if g[r][c]==bg:
    s=c
    while c<C and g[r][c]==bg:c+=1
    e=c
    if s>0 and e<C and g[r][s-1]==marker and g[r][e]==marker and e-s<=maxgap: mark.update((r,x) for x in range(s,e))
   else:c+=1
 # columns
 for c in range(C):
  r=0
  while r<R:
   if g[r][c]==bg:
    s=r
    while r<R and g[r][c]==bg:r+=1
    e=r
    if s>0 and e<R and g[s-1][c]==marker and g[e][c]==marker and e-s<=maxgap: mark.update((x,c) for x in range(s,e))
   else:r+=1
 out=[row[:] for row in g]
 for r,c in mark:out[r][c]=2
 return out,mark
